import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Κύκλος ζωής κράτησης","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/reservation-lifecycle.md","filePath":"el/plus/reservation-lifecycle.md"}'),l={name:"el/plus/reservation-lifecycle.md"};function o(s,t,i,n,c,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="κυκλος-ζωης-κρατησης" tabindex="-1">Κύκλος ζωής κράτησης <a class="header-anchor" href="#κυκλος-ζωης-κρατησης" aria-label="Permalink to &quot;Κύκλος ζωής κράτησης&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Πηγαίος κώδικας TransferBook+ v0.7.9. Το παρόν είναι τοπικό προσχέδιο προς έλεγχο, όχι επιβεβαίωση διαθεσιμότητας στην παραγωγή. Ελέγξτε την εγκατεστημένη έκδοση και τα δικαιώματά σας.</p></div><h2 id="καταστασεις" tabindex="-1">Καταστάσεις <a class="header-anchor" href="#καταστασεις" aria-label="Permalink to &quot;Καταστάσεις&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Κατάσταση</th><th>Σημασία</th></tr></thead><tbody><tr><td>New</td><td>Αρχική καταχώριση, πιθανή αναμονή προσφοράς ή ελέγχου</td></tr><tr><td>Confirmed</td><td>Επιβεβαιωμένη κράτηση</td></tr><tr><td>Assigned</td><td>Καταχωρισμένη ανάθεση οδηγού/οχήματος</td></tr><tr><td>In Transit</td><td>Διαδρομή σε εξέλιξη</td></tr><tr><td>Completed</td><td>Ολοκληρωμένη, τελική κατάσταση</td></tr><tr><td>Cancelled</td><td>Ακυρωμένη, τελική κατάσταση</td></tr></tbody></table><h2 id="διαδικασια-χειριστη" tabindex="-1">Διαδικασία χειριστή <a class="header-anchor" href="#διαδικασια-χειριστη" aria-label="Permalink to &quot;Διαδικασία χειριστή&quot;">​</a></h2><p>Ανοίξτε τη σωστή κράτηση και ελέγξτε την τρέχουσα κατάσταση. Χρησιμοποιήστε μόνο τις επιτρεπόμενες μεταβάσεις για τον ρόλο σας. Επιβεβαιώστε μόνο όταν πληρούνται οι απαιτήσεις τιμολόγησης και αποδοχής. Πριν από ακύρωση καταχωρίστε ουσιαστική αιτιολογία. Μετά την ολοκλήρωση ή ακύρωση επαληθεύστε την τελική κατάσταση χωρίς επαναφορά.</p><h2 id="αναμενομενο-αποτελεσμα-και-προβληματα" tabindex="-1">Αναμενόμενο αποτέλεσμα και προβλήματα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα-και-προβληματα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα και προβλήματα&quot;">​</a></h2><p>Το σύστημα καταγράφει μεταβάσεις και ιστορικό ελέγχου. Εκκρεμής προσφορά εμποδίζει επιβεβαίωση και ανάθεση μέχρι την έγκριση τιμής. Οι τελικές κρατήσεις δεν επιδέχονται συνήθη επεξεργασία. Ελέγξτε τις προϋποθέσεις αν μια μετάβαση απορρίπτεται.</p><p>Σχετικά: <a href="/el/plus/manual-quotations.html">χειροκίνητες προσφορές</a>, <a href="/el/plus/dispatch-schedule.html">πρόγραμμα αναθέσεων</a>.</p>',9)])])}const f=e(l,[["render",o]]);export{u as __pageData,f as default};
